// Package queue publishes reservation requests to SQS for the worker.
package queue

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"time"

	"github.com/aws/aws-sdk-go-v2/aws"
	"github.com/aws/aws-sdk-go-v2/service/sqs"

	"github.com/arunPdl02/pokedrop/backend/internal/reservations"
)

// EnvQueueURL carries the queue URL. It is generated by CloudFormation, so never hard-code it.
const EnvQueueURL = "RESERVATION_QUEUE_URL"

// sendTimeout bounds one enqueue (including SDK retries) well inside the Lambda timeout, so a
// stuck queue becomes a prompt 503 instead of a gateway timeout.
const sendTimeout = 5 * time.Second

type sqsAPI interface {
	SendMessage(context.Context, *sqs.SendMessageInput, ...func(*sqs.Options)) (*sqs.SendMessageOutput, error)
}

// Publisher implements reservations.Queue.
type Publisher struct {
	client sqsAPI
	url    string
}

var _ reservations.Queue = (*Publisher)(nil)

// NewPublisher returns a Publisher for the queue at url.
func NewPublisher(client sqsAPI, url string) *Publisher {
	return &Publisher{client: client, url: url}
}

// URLFromEnv reads the queue URL from the environment.
func URLFromEnv() (string, error) {
	url := os.Getenv(EnvQueueURL)
	if url == "" {
		return "", fmt.Errorf("%s is not set", EnvQueueURL)
	}
	return url, nil
}

// Enqueue sends msg and returns nil only after SQS has accepted it (a MessageId came back).
func (p *Publisher) Enqueue(ctx context.Context, msg reservations.QueueMessage) error {
	body, err := json.Marshal(msg)
	if err != nil {
		return fmt.Errorf("marshal message: %w", err)
	}
	ctx, cancel := context.WithTimeout(ctx, sendTimeout)
	defer cancel()

	out, err := p.client.SendMessage(ctx, &sqs.SendMessageInput{
		QueueUrl:    aws.String(p.url),
		MessageBody: aws.String(string(body)),
	})
	if err != nil {
		return fmt.Errorf("send message: %w", err)
	}
	if out == nil || aws.ToString(out.MessageId) == "" {
		return errors.New("send message: no message ID returned")
	}
	return nil
}
